import {chromium,expect} from '@playwright/test';import{readFile,writeFile,mkdir}from'node:fs/promises';
const rec=JSON.parse(await readFile('.local/step07-review/evidence/browser/evidence.json','utf8')),base='http://127.0.0.1:4383',out='.local/step07-review/evidence/poll-errors';await mkdir(out,{recursive:true});const browser=await chromium.launch({headless:true}),context=await browser.newContext({viewport:{width:1280,height:960}});await context.tracing.start({screenshots:true,snapshots:true,sources:true});const page=await context.newPage(),log={requests:[],responses:[],console:[],pageErrors:[],injected:'controlled read503; actual Build POST and backend state unchanged'};
page.on('request',r=>{if(r.url().includes('/studio'))log.requests.push({url:r.url(),time:Date.now()})});page.on('response',r=>{if(r.url().includes('/studio'))log.responses.push({url:r.url(),status:r.status(),time:Date.now()})});page.on('console',m=>log.console.push({type:m.type(),text:m.text()}));page.on('pageerror',e=>log.pageErrors.push(e.message));let inject=false,first=true,calls=0;
try{
 const projects=(await(await fetch(base+'/api/projects')).json()).projects;await page.goto(base);await page.getByRole('button',{name:projects.find(p=>p.id===rec.projectId).name,exact:true}).click();await expect(page.getByRole('button',{name:'构建当前配套',exact:true})).toBeEnabled({timeout:30000});await expect(page.getByAltText('当前配方处理水面')).toHaveAttribute('data-project-id',rec.projectId);await page.clock.install();
 const pattern='**/api/projects/'+rec.projectId+'/studio';await page.route(pattern,async route=>{calls++;if(inject){await route.fulfill({status:503,contentType:'application/json',body:JSON.stringify({error:{code:'SERVICE_UNAVAILABLE',message:'controlled unavailable studio read'}})});return}const response=await route.fetch();const data=await response.json();if(first){first=false;log.firstPayload=data;inject=true;}await route.fulfill({response})});
 const wait=page.waitForResponse(r=>r.request().method()==='POST'&&r.url().endsWith('/builds'));await page.getByRole('button',{name:'构建当前配套',exact:true}).click();const j=await(await wait).json();log.job=j.id;const item=page.getByRole('list',{name:'构建任务'}).getByRole('listitem').filter({hasText:j.id.slice(0,8)});await expect(item).toBeVisible();
 let actual;for(let n=0;n<400;n++){actual=await(await fetch(base+'/api/projects/'+rec.projectId+'/studio')).json();const job=actual.jobs.find(x=>x.id===j.id);if(['COMPLETED','FAILED'].includes(job.state)){log.backend=job;break}await new Promise(r=>setTimeout(r,100))}expect(log.backend.state).toBe('COMPLETED');log.callsWhenBackendCompleted=calls;
 const startBrowserTime=await page.evaluate(()=>Date.now());for(let n=0;n<80;n++){await page.clock.runFor(1000);await page.waitForTimeout(25);}log.virtualElapsedMs=(await page.evaluate(()=>Date.now()))-startBrowserTime;log.callsAfter80s=calls;log.ui=await item.innerText();log.requestsContinueAfter60s=calls>70;await page.screenshot({path:out+'/after80s.png',fullPage:true});
 inject=false;await page.clock.runFor(1000);await expect(item).toContainText('完成',{timeout:10000});log.recovered=await item.innerText();log.result=log.requestsContinueAfter60s?'UNBOUNDED_ERROR_POLL_REPRODUCED':'NO_UNBOUNDED_POLL_OBSERVED';expect(log.pageErrors).toEqual([]);
}catch(e){log.result='PROBE_FAILURE';log.failure=String(e);await page.screenshot({path:out+'/failure.png',fullPage:true}).catch(()=>{});throw e}finally{await page.unrouteAll({behavior:'ignoreErrors'});await writeFile(out+'/evidence.json',JSON.stringify(log,null,2)+'\n');await context.tracing.stop({path:'.local/step07-review/private/poll-errors-trace.zip'});await browser.close()}
console.log(log.result,log.callsAfter80s,log.virtualElapsedMs);
